--- a/cli/facts_test.go
+++ b/cli/facts_test.go
@@ -408,4 +408,34 @@
 		{"kogen intent usage: --slug needs a value", "intent", "usage", "--slug"},
 		{"kogen intent usage: unknown option '--lineage'", "intent", "usage", "--lineage=1"},
 	})
+}
+
+func resumeCompletion(t *testing.T, runs []object) string {
+	t.Helper()
+	return captureStdout(t, func() {
+		if completeCandidates("resume", nil, runs) != 0 {
+			t.Fatal("completion failed")
+		}
+	})
+}
+
+func TestResumeCompletionOffersOnlyResumableRuns(t *testing.T) {
+	runs := []object{
+		{"run_id": "run-x", "slug": "delta", "state": "interrupted", "resume_status": "unsupported"},
+		{"run_id": "run-a", "slug": "beta", "state": "build_blocked", "resume_status": "potentially_available"},
+		{"run_id": "run-c", "slug": "alpha", "state": "interrupted", "resume_status": "requires_validation"},
+		{"run_id": "run-b", "slug": "gamma", "state": "landed", "resume_status": "requires_validation"},
+		{"run_id": "run-d", "slug": "epsilon", "state": "already_present", "resume_status": "requires_validation"},
+	}
+	want := "run-a\tbeta build_blocked\nrun-c\talpha interrupted\n"
+	if got := resumeCompletion(t, runs); got != want {
+		t.Fatalf("resume candidates %q, want %q", got, want)
+	}
+	reversed := make([]object, len(runs))
+	for i, r := range runs {
+		reversed[len(runs)-1-i] = r
+	}
+	if got := resumeCompletion(t, reversed); got != want {
+		t.Fatalf("reversed input gave %q, want %q", got, want)
+	}
 }

